Every tier-specific agent (`OrchestratorAgent`, `MemoryAgent`, `QualityAgent`, all tier 2–5) is completely untested. The `base-agent.test.ts` uses a stub subclass and does not exercise any real agent logic.

**Missing: task routing, load balancing, health check logic (OrchestratorAgent)**
```ts
// tests/agents/tier1/orchestrator-agent.test.ts
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { OrchestratorAgent } from '../../../src/agents/tier1/orchestrator-agent';
import { resetEventBus, getEventBus } from '../../../src/core/event-bus';
import { resetStateManager, getStateManager } from '../../../src/core/state-manager';

describe('OrchestratorAgent', () => {
  let agent: OrchestratorAgent;

  beforeEach(async () => {
    resetEventBus(); resetStateManager();
    agent = new OrchestratorAgent({ eventBus: getEventBus(), stateManager: getStateManager() });
    await agent.initialize();
  });
  afterEach(async () => { await agent.shutdown(); });

  describe('process – route_task', () => {
    it('assigns task to agent with matching capability', async () => {
      const result = await agent.submitTask({
        id: 't1', type: 'route_task', payload: {
          action: 'route_task',
          task: { type: 'semantic_search', input: {}, priority: 'medium', targetCapabilities: ['vector_search'] },
        },
        priority: 'medium', status: 'pending', createdAt: new Date(), updatedAt: new Date(),
      });
      expect(result.output.result.assignedTo).toBe('memory');
    });

    it('returns null assignedTo when no agent matches capabilities', async () => {
      const result = await agent.submitTask({
        id: 't2', type: 'route_task', payload: {
          action: 'route_task',
          task: { type: 'unknown_task', input: {}, priority: 'low', targetCapabilities: ['nonexistent_cap'] },
        },
        priority: 'low', status: 'pending', createdAt: new Date(), updatedAt: new Date(),
      });
      expect(result.output.result.assignedTo).toBeUndefined();
    });

    it('performs health_check and returns status per agent', async () => {
      const result = await agent.submitTask({
        id: 't3', type: 'health_check', payload: { action: 'health_check' },
        priority: 'high', status: 'pending', createdAt: new Date(), updatedAt: new Date(),
      });
      expect(result.output.result.healthStatus).toBeDefined();
    });
  });

  describe('process – load balancing', () => {
    it('returns load distribution across agents', async () => {
      const result = await agent.submitTask({
        id: 't4', type: 'balance_load', payload: { action: 'balance_load' },
        priority: 'medium', status: 'pending', createdAt: new Date(), updatedAt: new Date(),
      });
      expect(result.output.result.loadDistribution).toBeDefined();
    });
  });
});
