**Missing: VectorStore operations, TTL expiry, consolidation (MemoryAgent)**
```ts
// tests/agents/tier1/memory-agent.test.ts
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { MemoryAgent } from '../../../src/agents/tier1/memory-agent';
import { resetEventBus, getEventBus } from '../../../src/core/event-bus';
import { resetStateManager, getStateManager } from '../../../src/core/state-manager';

describe('MemoryAgent', () => {
  let agent: MemoryAgent;

  beforeEach(async () => {
    resetEventBus(); resetStateManager();
    agent = new MemoryAgent({ eventBus: getEventBus(), stateManager: getStateManager() });
    await agent.initialize();
  });
  afterEach(async () => { await agent.shutdown(); });

  it('stores and retrieves an entry by id', async () => {
    const storeResult = await agent.submitTask({
      id: 'm1', type: 'store', status: 'pending', priority: 'medium',
      payload: { action: 'store', entry: { type: 'insight', content: 'ROAS improves on weekends', metadata: {} } },
      createdAt: new Date(), updatedAt: new Date(),
    });
    const entryId = storeResult.output.result.entry!.id;

    const retrieveResult = await agent.submitTask({
      id: 'm2', type: 'retrieve', status: 'pending', priority: 'medium',
      payload: { action: 'retrieve', query: { text: entryId } },
      createdAt: new Date(), updatedAt: new Date(),
    });
    expect(retrieveResult.output.result.entry?.content).toBe('ROAS improves on weekends');
  });

  it('returns stats after storing multiple entries', async () => {
    for (let i = 0; i < 3; i++) {
      await agent.submitTask({
        id: `m${i}`, type: 'store', status: 'pending', priority: 'low',
        payload: { action: 'store', entry: { type: 'pattern', content: `Pattern ${i}`, metadata: {} } },
        createdAt: new Date(), updatedAt: new Date(),
      });
    }
    const statsResult = await agent.submitTask({
      id: 'mstats', type: 'stats', status: 'pending', priority: 'low',
      payload: { action: 'stats' },
      createdAt: new Date(), updatedAt: new Date(),
    });
    expect(statsResult.output.result.stats!.totalEntries).toBeGreaterThanOrEqual(3);
    expect(statsResult.output.result.stats!.byType['pattern']).toBe(3);
  });

  it('cleanup removes expired TTL entries', async () => {
    await agent.submitTask({
      id: 'ttl1', type: 'store', status: 'pending', priority: 'low',
      payload: { action: 'store', entry: { type: 'session', content: 'ephemeral', metadata: {}, ttl: 1 } },
      createdAt: new Date(), updatedAt: new Date(),
    });
    await new Promise(r => setTimeout(r, 10)); // let TTL expire
    const cleaned = await agent.submitTask({
      id: 'cleanup1', type: 'cleanup', status: 'pending', priority: 'low',
      payload: { action: 'cleanup' },
      createdAt: new Date(), updatedAt: new Date(),
    });
    expect(cleaned.output.result.cleaned).toBeGreaterThanOrEqual(1);
  });
});
```

**Missing: validation rule application, truth scoring, gate pass/fail (QualityAgent)**
```ts
// tests/agents/tier1/quality-agent.test.ts
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { QualityAgent } from '../../../src/agents/tier1/quality-agent';
import { resetEventBus, getEventBus } from '../../../src/core/event-bus';
import { resetStateManager, getStateManager } from '../../../src/core/state-manager';

describe('QualityAgent', () => {
  let agent: QualityAgent;

  beforeEach(async () => {
    resetEventBus(); resetStateManager();
    agent = new QualityAgent({ eventBus: getEventBus(), stateManager: getStateManager() });
    await agent.initialize();
  });
  afterEach(async () => { await agent.shutdown(); });

  it('validate rejects data that fails budget_positive rule', async () => {
    const result = await agent.submitTask({
      id: 'q1', type: 'validate', status: 'pending', priority: 'high',
      payload: { action: 'validate', data: { budget: -100 }, context: { agentId: 'orchestrator', taskType: 'budget_check' } },
      createdAt: new Date(), updatedAt: new Date(),
    });
    expect(result.output.result.valid).toBe(false);
    const budgetRule = result.output.result.validationResults?.find(r => r.ruleId === 'budget_positive');
    expect(budgetRule?.passed).toBe(false);
    expect(budgetRule?.severity).toBe('error');
  });

  it('validate passes when budget is positive', async () => {
    const result = await agent.submitTask({
      id: 'q2', type: 'validate', status: 'pending', priority: 'high',
      payload: { action: 'validate', data: { budget: 500 }, context: { agentId: 'orchestrator', taskType: 'budget_check' }, rules: ['budget_positive'] },
      createdAt: new Date(), updatedAt: new Date(),
    });
    expect(result.output.result.valid).toBe(true);
  });

  it('gate blocks below threshold', async () => {
    const result = await agent.submitTask({
      id: 'q3', type: 'gate', status: 'pending', priority: 'high',
      payload: {
        action: 'gate', data: { budget: -50 },
        context: { agentId: 'coder', taskType: 'campaign_launch' },
        threshold: 0.9,
      },
      createdAt: new Date(), updatedAt: new Date(),
    });
    expect(result.output.result.gateDecision!.passed).toBe(false);
    expect(result.output.result.gateDecision!.blockers.length).toBeGreaterThan(0);
  });

  it('score_truth returns a truth score with all components', async () => {
    const result = await agent.submitTask({
      id: 'q4', type: 'score_truth', status: 'pending', priority: 'medium',
      payload: {
        action: 'score_truth',
        data: { prediction: 'ROAS will be 4.5', confidence: 0.7 },
        context: { agentId: 'simulation', taskType: 'forecast' },
      },
      createdAt: new Date(), updatedAt: new Date(),
    });
    const score = result.output.result.truthScore!;
    expect(score.overall).toBeGreaterThanOrEqual(0);
    expect(score.overall).toBeLessThanOrEqual(1);
    expect(score.components).toHaveProperty('consistency');
    expect(score.components).toHaveProperty('plausibility');
  });
});
