**Missing: recordMetrics, generateCampaignReport, detectAnomalies, compareEntities (AnalyticsService)**
```ts
// tests/services/analytics-service.test.ts
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { AnalyticsService } from '../../src/services/analytics-service';
import { resetEventBus } from '../../src/core/event-bus';
import { resetStateManager, getStateManager } from '../../src/core/state-manager';
import type { MetricSnapshot } from '../../src/services/analytics-service';

function makeSnapshot(overrides: Partial<MetricSnapshot> = {}): MetricSnapshot {
  return { timestamp: new Date(), impressions: 10000, clicks: 300, conversions: 30,
    spend: 500, revenue: 2000, ctr: 0.03, cpc: 1.67, cpa: 16.67, roas: 4.0, ...overrides };
}

describe('AnalyticsService', () => {
  let service: AnalyticsService;

  beforeEach(() => {
    resetEventBus(); resetStateManager();
    service = new AnalyticsService();
  });
  afterEach(() => { resetEventBus(); resetStateManager(); });

  describe('recordMetrics', () => {
    it('accumulates metric history per entity', () => {
      service.recordMetrics('campaign-1', makeSnapshot());
      service.recordMetrics('campaign-1', makeSnapshot({ impressions: 20000 }));
      const series = service.getTimeSeries('campaign-1');
      expect(series).toHaveLength(2);
    });

    it('stores separate histories for different entities', () => {
      service.recordMetrics('campaign-1', makeSnapshot());
      service.recordMetrics('campaign-2', makeSnapshot({ impressions: 5000 }));
      expect(service.getTimeSeries('campaign-1')).toHaveLength(1);
      expect(service.getTimeSeries('campaign-2')).toHaveLength(1);
    });
  });

  describe('generateCampaignReport', () => {
    it('throws for unknown campaign id', () => {
      expect(() => service.generateCampaignReport('unknown-id')).toThrow();
    });

    it('returns report with trends and insights for known campaign', () => {
      const sm = getStateManager();
      sm.updateCampaign('c1', { id: 'c1', name: 'Test', status: 'active', spent: 500,
        metrics: { impressions: 1000, clicks: 50, conversions: 5, ctr: 0.05, cpc: 10, cpa: 100, roas: 2, revenue: 1000 } });
      const report = service.generateCampaignReport('c1');
      expect(report.entityId).toBe('c1');
      expect(report.trends).toBeDefined();
      expect(Array.isArray(report.insights)).toBe(true);
    });
  });

  describe('detectAnomalies', () => {
    it('returns empty array when insufficient history', () => {
      service.recordMetrics('e1', makeSnapshot());
      const anomalies = service.detectAnomalies('e1');
      expect(anomalies).toEqual([]);
    });

    it('flags anomaly when metric spikes beyond 2 standard deviations', () => {
      for (let i = 0; i < 5; i++) service.recordMetrics('e2', makeSnapshot({ spend: 500 }));
      service.recordMetrics('e2', makeSnapshot({ spend: 50000 })); // spike
      const anomalies = service.detectAnomalies('e2');
      expect(anomalies.some(a => a.metric === 'spend')).toBe(true);
    });
  });

  describe('calculateBenchmarks', () => {
    it('returns benchmarks with industry averages', () => {
      service.recordMetrics('e3', makeSnapshot());
      const benchmarks = service.calculateBenchmarks('e3');
      expect(benchmarks.length).toBeGreaterThan(0);
      benchmarks.forEach(b => {
        expect(b.percentile).toBeGreaterThanOrEqual(0);
        expect(b.percentile).toBeLessThanOrEqual(100);
      });
    });
  });
});
