**Missing: attribution models, incrementality calculation, causal graph (AttributionService)**
```ts
// tests/services/attribution-service.test.ts
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { AttributionService } from '../../src/services/attribution-service';
import { resetEventBus } from '../../src/core/event-bus';
import { resetStateManager } from '../../src/core/state-manager';
import type { Touchpoint } from '../../src/types';

function makeTouchpoint(overrides: Partial<Touchpoint> = {}): Touchpoint {
  return { id: `tp-${Math.random()}`, userId: 'user-1', platform: 'google_ads',
    campaignId: 'c1', timestamp: new Date(), type: 'impression', ...overrides };
}

describe('AttributionService', () => {
  let service: AttributionService;

  beforeEach(() => { resetEventBus(); resetStateManager(); service = new AttributionService(); });
  afterEach(() => { resetEventBus(); resetStateManager(); });

  describe('recordTouchpoint / recordConversion', () => {
    it('records touchpoints without throwing', () => {
      expect(() => service.recordTouchpoint(makeTouchpoint())).not.toThrow();
    });

    it('records conversion and associates touchpoints for user', () => {
      service.recordTouchpoint(makeTouchpoint({ userId: 'u1', campaignId: 'c1' }));
      expect(() => service.recordConversion('u1', 100)).not.toThrow();
    });
  });

  describe('calculateAttribution', () => {
    it('first_touch attributes 100% to first touchpoint campaign', () => {
      service.recordTouchpoint(makeTouchpoint({ userId: 'u2', campaignId: 'first-camp', type: 'click' }));
      service.recordTouchpoint(makeTouchpoint({ userId: 'u2', campaignId: 'last-camp', type: 'click' }));
      service.recordConversion('u2', 200);

      const results = service.calculateAttribution('c1', { type: 'first_touch' });
      const firstCamp = results.find(r => r.campaignId === 'first-camp');
      expect(firstCamp?.contribution).toBeCloseTo(1.0);
    });

    it('linear model distributes credit equally across touchpoints', () => {
      service.recordTouchpoint(makeTouchpoint({ userId: 'u3', campaignId: 'c-a', type: 'click' }));
      service.recordTouchpoint(makeTouchpoint({ userId: 'u3', campaignId: 'c-b', type: 'click' }));
      service.recordConversion('u3', 100);

      const results = service.calculateAttribution('c-a', { type: 'linear' });
      results.forEach(r => expect(r.contribution).toBeGreaterThan(0));
      const total = results.reduce((s, r) => s + r.contribution, 0);
      expect(total).toBeCloseTo(1.0, 1);
    });

    it('returns empty array when no conversions recorded for campaign', () => {
      const results = service.calculateAttribution('nonexistent', { type: 'last_touch' });
      expect(results).toEqual([]);
    });
  });

  describe('measureIncrementality', () => {
    it('returns result with pValue when test data is provided', () => {
      const result = service.measureIncrementality('c1', {
        testGroup: { conversions: 120, spend: 1000, impressions: 50000, clicks: 1500, revenue: 6000 },
        controlGroup: { conversions: 100, spend: 0, impressions: 50000, clicks: 0, revenue: 5000 },
        testPeriod: { start: new Date('2026-01-01'), end: new Date('2026-01-31') },
        testType: 'geo_holdout',
      });
      expect(result.incrementalConversions).toBeGreaterThanOrEqual(0);
      expect(result.pValue).toBeGreaterThanOrEqual(0);
      expect(result.pValue).toBeLessThanOrEqual(1);
      expect(result.confidence).toBeGreaterThanOrEqual(0);
    });
  });
});
