```ts
// tests/services/creative-service.test.ts
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { CreativeService } from '../../src/services/creative-service';
import { resetEventBus } from '../../src/core/event-bus';
import { resetStateManager } from '../../src/core/state-manager';

describe('CreativeService', () => {
  let service: CreativeService;

  beforeEach(() => { resetEventBus(); resetStateManager(); service = new CreativeService(); });
  afterEach(() => { resetEventBus(); resetStateManager(); });

  describe('createCreative', () => {
    it('creates creative with generated id and draft status', async () => {
      const creative = await service.createCreative({
        name: 'Test Ad', type: 'display', platform: 'google_ads',
        content: { headline: 'Buy Now', body: 'Great deal', callToAction: 'Shop' },
      });
      expect(creative.id).toBeDefined();
      expect(creative.status).toBe('draft');
      expect(creative.name).toBe('Test Ad');
    });

    it('throws when name is empty', async () => {
      await expect(service.createCreative({
        name: '', type: 'video', platform: 'meta', content: {},
      })).rejects.toThrow();
    });
  });

  describe('activateCreative', () => {
    it('transitions status from draft to active', async () => {
      const creative = await service.createCreative({
        name: 'Ad', type: 'display', platform: 'google_ads', content: {},
      });
      const activated = await service.activateCreative(creative.id);
      expect(activated.status).toBe('active');
    });

    it('throws for unknown creative id', async () => {
      await expect(service.activateCreative('no-such-id')).rejects.toThrow();
    });
  });

  describe('analyzePerformance', () => {
    it('returns recommendedAction=replace when fatigue is critical', async () => {
      const creative = await service.createCreative({
        name: 'Fatigued Ad', type: 'video', platform: 'meta',
        content: { headline: 'Old hook' },
      });
      // inject high-fatigue metrics directly
      creative.metrics = { impressions: 1_000_000, clicks: 1000, conversions: 5,
        ctr: 0.001, cpc: 100, cpa: 200, roas: 0.5, revenue: 1000, fatigueScore: 0.95 };

      const perf = service.analyzePerformance(creative);
      expect(perf.recommendedAction).toBe('replace');
      expect(perf.fatigueLevel).toBeGreaterThan(0.8);
    });

    it('returns recommendedAction=continue for healthy creative', async () => {
      const creative = await service.createCreative({
        name: 'Fresh Ad', type: 'display', platform: 'google_ads', content: {},
      });
      creative.metrics = { impressions: 50000, clicks: 2000, conversions: 200,
        ctr: 0.04, cpc: 0.5, cpa: 5, roas: 8, revenue: 10000, fatigueScore: 0.1 };

      const perf = service.analyzePerformance(creative);
      expect(perf.recommendedAction).toBe('continue');
    });
  });

  describe('generateVariants', () => {
    it('generates the requested number of variants', async () => {
      const creative = await service.createCreative({
        name: 'Base', type: 'display', platform: 'google_ads',
        content: { headline: 'Original', body: 'Body text', callToAction: 'Click here' },
      });
      const variants = service.generateVariants(creative, 3);
      expect(variants).toHaveLength(3);
      variants.forEach(v => {
        expect(v.parentId).toBe(creative.id);
        expect(v.id).not.toBe(creative.id);
      });
    });
  });

  describe('cloneCreative', () => {
    it('creates a copy with a new id', async () => {
      const original = await service.createCreative({
        name: 'Original', type: 'video', platform: 'tiktok', content: {},
      });
      const clone = await service.cloneCreative(original.id);
      expect(clone.id).not.toBe(original.id);
      expect(clone.name).toContain('Original');
    });
  });
});
