The existing `base-agent.test.ts` only tests the happy path. The error handling in `submitTask` (lines ~147–200 in `base-agent.ts`) — task failure metrics update, `lastError`, error event emission, status reset to `idle` — has no coverage.

```ts
// Add to tests/agents/base-agent.test.ts — inside describe('BaseAgent')
describe('error handling in submitTask', () => {
  it('increments error count when process throws', async () => {
    class FailingAgent extends BaseAgent {
      protected async process() { throw new Error('intentional failure'); }
      protected async onInitialize() {}
      protected async onShutdown() {}
      protected getSubscribedEvents() { return []; }
      protected async handleEvent() {}
    }
    const failing = new FailingAgent(eventBus, stateManager);
    await failing.initialize();

    await expect(failing.submitTask({
      id: 'fail-1', type: 'any', priority: 'high', status: 'pending',
      payload: {}, createdAt: new Date(), updatedAt: new Date(),
    })).rejects.toThrow('intentional failure');

    expect(failing.getErrorCount()).toBe(1);
    await failing.shutdown();
  });

  it('resets status to idle after error', async () => {
    class FailingAgent extends BaseAgent {
      protected async process() { throw new Error('fail'); }
      protected async onInitialize() {}
      protected async onShutdown() {}
      protected getSubscribedEvents() { return []; }
      protected async handleEvent() {}
    }
    const failing = new FailingAgent(eventBus, stateManager);
    await failing.initialize();

    await expect(failing.submitTask({
      id: 'fail-2', type: 'any', priority: 'medium', status: 'pending',
      payload: {}, createdAt: new Date(), updatedAt: new Date(),
    })).rejects.toThrow();

    // After failure, agent should return to idle not remain stuck on 'processing'
    expect(failing.getStatus()).toBe('idle');
    await failing.shutdown();
  });

  it('throws when task submitted during shutdown', async () => {
    const shutdownPromise = agent.shutdown();
    await expect(agent.submitTask({
      id: 'shutdown-race', type: 'any', priority: 'low', status: 'pending',
      payload: {}, createdAt: new Date(), updatedAt: new Date(),
    })).rejects.toThrow('shutting down');
    await shutdownPromise;
  });
});
