// Add to tests/core/event-bus.test.ts
describe('error handling', () => {
  it('calls custom errorHandler when subscriber throws', () => {
    const errorHandler = vi.fn();
    const bus = new EventBus({ errorHandler });
    bus.subscribe('err.event', () => { throw new Error('handler failure'); });
    bus.publish({ id: '1', type: 'err.event', timestamp: new Date(), source: 'test', payload: {} });
    expect(errorHandler).toHaveBeenCalledOnce();
    expect(errorHandler.mock.calls[0][0]).toBeInstanceOf(Error);
  });
});

describe('priority ordering', () => {
  it('delivers to higher-priority subscriber first', () => {
    const order: number[] = [];
    eventBus.subscribe('pri.event', () => { order.push(1); }, { priority: 1 });
    eventBus.subscribe('pri.event', () => { order.push(10); }, { priority: 10 });
    eventBus.publish({ id: '1', type: 'pri.event', timestamp: new Date(), source: 'test', payload: {} });
    expect(order[0]).toBe(10);
  });
});

describe('history cap', () => {
  it('does not exceed maxEventHistory', () => {
    const bus = new EventBus({ maxEventHistory: 3 });
    for (let i = 0; i < 10; i++) {
      bus.publish({ id: String(i), type: 'cap.test', timestamp: new Date(), source: 'test', payload: {} });
    }
    expect(bus.getEventHistory().length).toBeLessThanOrEqual(3);
  });
});
