import type { MetricSnapshot } from '../../src/services/analytics-service';

function makeSnapshot(overrides: Partial<MetricSnapshot> = {}): MetricSnapshot {
  return { timestamp: new Date(), impressions: 10000, clicks: 300, conversions: 30,
    spend: 500, revenue: 2000, ctr: 0.03, cpc: 1.67, cpa: 16.67, roas: 4.0, ...overrides };
}

describe('AnalyticsService', () => {
  let service: AnalyticsService;

  beforeEach(() => {
    resetEventBus(); resetStateManager();
    service = new AnalyticsService();
  });
  afterEach(() => { resetEventBus(); resetStateManager(); });

  describe('recordMetrics', () => {
    it('accumulates metric history per entity', () => {
      service.recordMetrics('campaign-1', makeSnapshot());
      service.recordMetrics('campaign-1', makeSnapshot({ impressions: 20000 }));
      const series = service.getTimeSeries('campaign-1');
      expect(series).toHaveLength(2);
    });

    it('stores separate histories for different entities', () => {
      service.recordMetrics('campaign-1', makeSnapshot());
      service.recordMetrics('campaign-2', makeSnapshot({ impressions: 5000 }));
      expect(service.getTimeSeries('campaign-1')).toHaveLength(1);
      expect(service.getTimeSeries('campaign-2')).toHaveLength(1);
    });
  });

  describe('generateCampaignReport', () => {
    it('throws for unknown campaign id', () => {
      expect(() => service.generateCampaignReport('unknown-id')).toThrow();
    });

    it('returns report with trends and insights for known campaign', () => {
      const sm = getStateManager();
      sm.updateCampaign('c1', { id: 'c1', name: 'Test', status: 'active', spent: 500,
