  });

  it('resets status to idle after error', async () => {
    class FailingAgent extends BaseAgent {
      protected async process() { throw new Error('fail'); }
      protected async onInitialize() {}
      protected async onShutdown() {}
      protected getSubscribedEvents() { return []; }
      protected async handleEvent() {}
    }
