import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { RiskDetectionAgent } from '../../../src/agents/tier2/risk-detection-agent';
import { resetEventBus, getEventBus } from '../../../src/core/event-bus';
import { resetStateManager, getStateManager } from '../../../src/core/state-manager';

describe('RiskDetectionAgent', () => {
  let agent: RiskDetectionAgent;

  beforeEach(async () => {
    resetEventBus(); resetStateManager();
    agent = new RiskDetectionAgent({ eventBus: getEventBus(), stateManager: getStateManager() });
    await agent.initialize();
  });
  afterEach(async () => { await agent.shutdown(); });

  describe('detect_fraud', () => {
    it('flags click farm when click rate exceeds threshold', async () => {
      const result = await agent.submitTask({
        id: 'r1', type: 'detect_fraud', status: 'pending', priority: 'high',
        payload: {
          action: 'detect_fraud',
          metrics: {
            impressions: 10000, clicks: 3000, conversions: 1, spend: 500,
            clickPatterns: [
              { timestamp: new Date(), ip: '1.2.3.4', userAgent: 'bot/1.0', geo: 'XX' },
              { timestamp: new Date(), ip: '1.2.3.4', userAgent: 'bot/1.0', geo: 'XX' },
            ],
          },
        },
        createdAt: new Date(), updatedAt: new Date(),
      });
      expect(result.output.result.fraudIndicators!.length).toBeGreaterThan(0);
      expect(result.output.result.riskScore).toBeGreaterThan(0.5);
    });

    it('returns no fraud indicators for clean traffic', async () => {
      const result = await agent.submitTask({
        id: 'r2', type: 'detect_fraud', status: 'pending', priority: 'high',
        payload: {
          action: 'detect_fraud',
          metrics: { impressions: 100000, clicks: 2000, conversions: 200, spend: 1000 },
        },
        createdAt: new Date(), updatedAt: new Date(),
      });
      expect(result.output.result.riskScore).toBeLessThan(0.3);
    });
  });

  describe('monitor_pacing', () => {
    it('predicts budget overspend when pacing rate is high', async () => {
      const start = new Date();
      start.setHours(0, 0, 0, 0);
      const now = new Date();
      now.setHours(6, 0, 0, 0); // 25% through day

      const result = await agent.submitTask({
        id: 'r3', type: 'monitor_pacing', status: 'pending', priority: 'medium',
        payload: {
          action: 'monitor_pacing',
          campaign: { id: 'c1', dailyBudget: 1000, spent: 600 }, // 60% spent in 25% of day
          timeWindow: { start, end: now },
        },
        createdAt: new Date(), updatedAt: new Date(),
      });
      expect(result.output.result.pacingAnalysis!.projection.willExceedBudget).toBe(true);
    });
  });
});

