import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { SimulationAgent } from '../../../src/agents/tier2/simulation-agent';
import { resetEventBus, getEventBus } from '../../../src/core/event-bus';
import { resetStateManager, getStateManager } from '../../../src/core/state-manager';

describe('SimulationAgent', () => {
  let agent: SimulationAgent;

  beforeEach(async () => {
    resetEventBus(); resetStateManager();
    agent = new SimulationAgent({ eventBus: getEventBus(), stateManager: getStateManager() });
    await agent.initialize();
  });
  afterEach(async () => { await agent.shutdown(); });

  it('forecast returns confidence intervals and risk metrics', async () => {
    const result = await agent.submitTask({
      id: 's1', type: 'forecast', status: 'pending', priority: 'medium',
      payload: {
        action: 'forecast',
        campaign: {
          id: 'c1', dailyBudget: 500,
          metrics: { impressions: 10000, clicks: 300, conversions: 30, ctr: 0.03, cpc: 1.67, cpa: 16.67, roas: 4, revenue: 2000 },
        },
        parameters: { iterations: 1000, confidenceLevel: 0.95, timeHorizon: 30 },
      },
      createdAt: new Date(), updatedAt: new Date(),
    });
    const forecast = result.output.result.forecast!;
    expect(forecast.confidenceInterval.roas[0]).toBeLessThan(forecast.confidenceInterval.roas[1]);
    expect(forecast.riskMetrics.probabilityOfLoss).toBeGreaterThanOrEqual(0);
    expect(forecast.riskMetrics.probabilityOfLoss).toBeLessThanOrEqual(1);
  });

  it('optimize returns dailyBudget and bidAmount', async () => {
    const result = await agent.submitTask({
      id: 's2', type: 'optimize', status: 'pending', priority: 'high',
      payload: {
        action: 'optimize',
        campaign: { id: 'c2', dailyBudget: 300,
          metrics: { impressions: 5000, clicks: 100, conversions: 10, ctr: 0.02, cpc: 3, cpa: 30, roas: 3, revenue: 900 } },
        parameters: { iterations: 500, confidenceLevel: 0.9, timeHorizon: 14,
          budgetRange: [100, 1000], bidRange: [0.5, 5] },
      },
      createdAt: new Date(), updatedAt: new Date(),
    });
    const opt = result.output.result.optimalConfig!;
    expect(opt.dailyBudget).toBeGreaterThan(0);
    expect(opt.bidAmount).toBeGreaterThan(0);
    expect(opt.confidence).toBeGreaterThan(0);
  });

  it('sensitivity returns elasticity per parameter', async () => {
    const result = await agent.submitTask({
      id: 's3', type: 'sensitivity', status: 'pending', priority: 'low',
      payload: {
        action: 'sensitivity',
        campaign: { id: 'c3', dailyBudget: 500,
          metrics: { impressions: 10000, clicks: 200, conversions: 20, ctr: 0.02, cpc: 2.5, cpa: 25, roas: 3, revenue: 1500 } },
      },
      createdAt: new Date(), updatedAt: new Date(),
    });
    expect(result.output.result.sensitivityAnalysis!.length).toBeGreaterThan(0);
    result.output.result.sensitivityAnalysis!.forEach(s => {
      expect(typeof s.elasticity).toBe('number');
    });
  });
});

