  let quality: QualityAgent;

  beforeEach(async () => {
    resetEventBus(); resetStateManager();
    const eventBus = getEventBus();
    const stateManager = getStateManager();
    orchestrator = new OrchestratorAgent({ eventBus, stateManager });
    quality = new QualityAgent({ eventBus, stateManager });
    await orchestrator.initialize();
    await quality.initialize();
  });
  afterEach(async () => {
    await orchestrator.shutdown();
    await quality.shutdown();
  });

  it('orchestrator routes task and quality validates output via event bus', async () => {
    const receivedEvents: string[] = [];
    getEventBus().subscribe('task.started', () => receivedEvents.push('task.started'));
